const UI_UK=Object.fromEntries(Object.entries(UI_EN).map(([uk,en])=>[en,uk])) as Record<string,string>;
const ui=(ua:string,en:string)=>getLang()==="uk"?ua:en;
const roleLabel=(r:Role)=>r==="ADMIN"?ui("Адміністратор","Administrator"):r==="MANAGER"?ui("Менеджер","Manager"):ui("Працівник","Employee");
const translateStatic=(text:string,lang:Lang)=>{const trimmed=text.trim();if(!trimmed)return text;const map=lang==="en"?UI_EN:UI_UK;const direct=map[trimmed];if(direct)return text.replace(trimmed,direct);let out=text;if(lang==="en"){
 out=out.replace(/Було відтерміновано до/g,"Postponed until").replace(/Коментар:/g,"Comment:").replace(/Поточний термін:/g,"Current due date:").replace(/Старт:/g,"Start:").replace(/До:/g,"Due:").replace(/Створив:/g,"Created by:").replace(/ очікує рішення/g," awaiting decision").replace(/ виконавців/g," assignees").replace(/ з (\d+) виконано/g," of $1 completed").replace(/Увага:/g,"Attention:").replace(/Найближчий термін:/g,"Nearest deadline:").replace(/запис скоро завершиться/g,"item is due soon").replace(/записи скоро завершаться/g,"items are due soon").replace(/Перевірте завдання та чеклісти з дедлайном у найближчі 24 години\./g,"Review tasks and checklists due within the next 24 hours.");
 }else{
 out=out.replace(/Postponed until/g,"Було відтерміновано до").replace(/Comment:/g,"Коментар:").replace(/Current due date:/g,"Поточний термін:").replace(/Start:/g,"Старт:").replace(/Due:/g,"До:").replace(/Created by:/g,"Створив:").replace(/ awaiting decision/g," очікує рішення").replace(/ assignees/g," виконавців").replace(/ of (\d+) completed/g," з $1 виконано").replace(/Attention:/g,"Увага:").replace(/Nearest deadline:/g,"Найближчий термін:").replace(/item is due soon/g,"запис скоро завершиться").replace(/items are due soon/g,"записи скоро завершаться").replace(/Review tasks and checklists due within the next 24 hours\./g,"Перевірте завдання та чеклісти з дедлайном у найближчі 24 години.");
 }return out};
const applyLanguage=(lang:Lang)=>{document.documentElement.lang=lang==="uk"?"uk":"en";const root=document.getElementById("root");if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes:Text[]=[];while(walker.nextNode())nodes.push(walker.currentNode as Text);for(const n of nodes){const next=translateStatic(n.nodeValue||"",lang);if(next!==n.nodeValue)n.nodeValue=next}root.querySelectorAll<HTMLElement>("[placeholder],[title]").forEach(el=>{for(const attr of ["placeholder","title"]){const v=el.getAttribute(attr);if(v){const next=translateStatic(v,lang);if(next!==v)el.setAttribute(attr,next)}}})};
function LanguageSwitch({lang,onChange}:{lang:Lang;onChange:(l:Lang)=>void}){return <div className="language-switch"><button type="button" className={lang==="en"?"active":""} onClick={()=>onChange("en")}>EN</button><button type="button" className={lang==="uk"?"active":""} onClick={()=>onChange("uk")}>UA</button></div>}
const api=async(path:string,options:RequestInit={})=>{const token=localStorage.getItem("cf_token");const headers:any={...(options.headers||{})};if(!(options.body instanceof FormData))headers["Content-Type"]="application/json";if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(API+path,{...options,headers});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||"Помилка запиту");return data};
const fmt=(v:string)=>new Date(v).toLocaleString(getLang()==="uk"?"uk-UA":"en-GB",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:false});
const toLocalInput=(v?:string)=>{const d=v?new Date(v):new Date();const off=d.getTimezoneOffset();return new Date(d.getTime()-off*60000).toISOString().slice(0,16)};
const assignees=(w:Work)=>w.assignments?.map(a=>a.user).filter(Boolean).length?w.assignments!.map(a=>a.user):[w.assignee];

function Login({onLogin,lang,onLang}:{onLogin:(u:User)=>void;lang:Lang;onLang:(l:Lang)=>void}){const[username,setUsername]=useState(""),[password,setPassword]=useState(""),[err,setErr]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();setErr("");try{const d=await api("/auth/login",{method:"POST",body:JSON.stringify({username,password})});localStorage.setItem("cf_token",d.token);localStorage.setItem("cf_user",JSON.stringify(d.user));onLogin(d.user)}catch(e:any){setErr(e.message)}};return <div className="auth-page"><div className="auth-panel"><div className="auth-top"><LanguageSwitch lang={lang} onChange={onLang}/></div><div className="brand big"><div className="brand-mark"><ClipboardCheck/></div><div><b>CheckFlow</b><span>Контроль без хаосу</span></div></div><h1>Вхід до системи</h1><p className="muted">Чеклісти, завдання, дедлайни та контроль виконання.</p><form autoComplete="off" onSubmit={submit}><label>Ім'я користувача<input autoComplete="off" value={username} onChange={e=>setUsername(e.target.value)}/></label><label>Пароль<input autoComplete="off" value={password} onChange={e=>setPassword(e.target.value)} type="password"/></label>{err&&<div className="error">{err}</div>}<button className="primary wide">Увійти</button></form></div><div className="auth-art"><div className="art-card"><CheckCircle2/><b>Контроль виконання</b><span>Чеклісти та окремі завдання</span></div><div className="art-card"><CalendarClock/><b>Погодження термінів</b><span>Відтермінування тільки після рішення керівника</span></div></div></div>}
function ChangePassword({user,onChanged}:{user:User;onChanged:(u:User)=>void}){const[currentPassword,setCurrentPassword]=useState(""),[newPassword,setNewPassword]=useState(""),[confirm,setConfirm]=useState(""),[err,setErr]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();setErr("");if(newPassword!==confirm){setErr(ui("Нові паролі не співпадають","New passwords do not match"));return}try{const d=await api("/auth/change-password",{method:"POST",body:JSON.stringify({currentPassword,newPassword})});onChanged(d.user)}catch(e:any){setErr(e.message)}};return <div className="auth-page single"><div className="auth-panel password-panel"><div className="brand big"><div className="brand-mark"><ShieldCheck/></div><div><b>CheckFlow</b><span>Безпека облікового запису</span></div></div><h1>Змініть тимчасовий пароль</h1><p className="muted">{user.name}, {ui("встановіть власний пароль. Мінімум 8 символів.","set your own password. Minimum 8 characters.")}</p><form onSubmit={submit}><label>Поточний пароль<input required type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></label><label>Новий пароль<input required minLength={8} type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></label><label>Повторіть пароль<input required minLength={8} type="password" value={confirm} onChange={e=>setConfirm(e.target.value)}/></label>{err&&<div className="error">{err}</div>}<button className="primary wide">Змінити пароль і продовжити</button></form></div></div>}

function HeaderClock(){const[now,setNow]=useState(new Date());useEffect(()=>{const t=setInterval(()=>setNow(new Date()),30000);return()=>clearInterval(t)},[]);return <span>{now.toLocaleDateString(getLang()==="uk"?"uk-UA":"en-GB",{weekday:"long",day:"numeric",month:"long"})} · {now.toLocaleTimeString(getLang()==="uk"?"uk-UA":"en-GB",{hour:"2-digit",minute:"2-digit",hour12:false})}</span>}

function App(){const[user,setUser]=useState<User|null>(()=>{try{return JSON.parse(localStorage.getItem("cf_user")||"null")}catch{return null}}),[theme,setTheme]=useState(localStorage.getItem("cf_theme")||"light"),[lang,setLang]=useState<Lang>(()=>getLang()),[page,setPage]=useState<"dashboard"|"history"|"users">("dashboard"),[selected,setSelected]=useState<string|null>(null),[createOpen,setCreateOpen]=useState(false),[mobileNav,setMobileNav]=useState(false),[reload,setReload]=useState(0);const changeLang=(l:Lang)=>{localStorage.setItem("cf_lang",l);setLang(l)};useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem("cf_theme",theme)},[theme]);useEffect(()=>{const run=()=>applyLanguage(lang);run();const target=document.getElementById("root");if(!target)return;const obs=new MutationObserver(()=>queueMicrotask(run));obs.observe(target,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:["placeholder","title"]});return()=>obs.disconnect()},[lang]);if(!user)return <Login onLogin={setUser} lang={lang} onLang={changeLang}/>;if(user.mustChangePassword)return <ChangePassword user={user} onChanged={u=>{localStorage.setItem("cf_user",JSON.stringify(u));setUser(u)}}/>;const logout=()=>{localStorage.removeItem("cf_token");localStorage.removeItem("cf_user");setUser(null)};const title=selected?"Деталі":page==="dashboard"?"Робочий простір":page==="history"?"Історія":"Користувачі";return <div className="app-shell"><aside className={mobileNav?"sidebar open":"sidebar"}><div className="brand"><div className="brand-mark"><ClipboardCheck/></div><div><b>CheckFlow</b><span>Workspace</span></div></div><nav><button className={page==="dashboard"&&!selected?"active":""} onClick={()=>{setPage("dashboard");setSelected(null);setMobileNav(false)}}><ClipboardCheck/>Робота</button><button className={page==="history"&&!selected?"active":""} onClick={()=>{setPage("history");setSelected(null);setMobileNav(false)}}><History/>Історія</button>{user.role!=="EMPLOYEE"&&<button className={page==="users"?"active":""} onClick={()=>{setPage("users");setSelected(null);setMobileNav(false)}}><Users/>Користувачі</button>}</nav><div className="sidebar-user"><div className="avatar">{user.name.slice(0,1).toUpperCase()}</div><div><b>{user.name}</b><span>{user.position}</span></div></div></aside><main><header><button className="icon mobile" onClick={()=>setMobileNav(!mobileNav)}><Menu/></button><div className="header-title"><b>{title}</b><HeaderClock/></div><div className="header-actions"><LanguageSwitch lang={lang} onChange={changeLang}/><button className="icon" onClick={()=>setTheme(theme==="light"?"dark":"light")}>{theme==="light"?<Moon/>:<Sun/>}</button><button className="icon" onClick={logout}><LogOut/></button></div></header><div className="content">{selected?<WorkDetail id={selected} user={user} back={()=>setSelected(null)} changed={()=>setReload(x=>x+1)}/>:page==="dashboard"?<Dashboard key={reload} user={user} open={setSelected} create={()=>setCreateOpen(true)}/>:page==="history"?<HistoryPage key={reload} user={user} open={setSelected}/>:<UsersPage user={user}/>}</div></main>{createOpen&&<WorkEditor close={()=>setCreateOpen(false)} done={()=>{setCreateOpen(false);setReload(x=>x+1)}}/>}</div>}

function Dashboard({user,open,create}:{user:User;open:(id:string)=>void;create:()=>void}){const[data,setData]=useState<Work[]>([]),[pending,setPending]=useState<PendingRequest[]>([]),[loading,setLoading]=useState(true),[filter,setFilter]=useState("ALL"),[sort,setSort]=useState("DUE_ASC");const load=()=>Promise.all([api("/checklists").then(setData),user.role!=="EMPLOYEE"?api("/postpone-requests").then(setPending):Promise.resolve()]).finally(()=>setLoading(false));useEffect(()=>{load()},[]);const workingStatuses:Status[]=["OPEN","IN_PROGRESS","BLOCKED"];const counts=useMemo(()=>({all:data.length,done:data.filter(x=>x.status==="COMPLETED").length,progress:data.filter(x=>x.status==="SCHEDULED").length,working:data.filter(x=>workingStatuses.includes(x.status)).length,over:data.filter(x=>x.status==="OVERDUE").length}),[data]);const dueSoon=useMemo(()=>{const now=Date.now(),limit=now+24*60*60*1000;return data.filter(x=>!["COMPLETED","OVERDUE"].includes(x.status)&&new Date(x.dueDate).getTime()>now&&new Date(x.dueDate).getTime()<=limit)},[data]);const filtered=filter==="ALL"?data:filter==="TASK"?data.filter(x=>x.type==="TASK"):filter==="CHECKLIST"?data.filter(x=>x.type==="CHECKLIST"):filter==="WORKING"?data.filter(x=>workingStatuses.includes(x.status)):data.filter(x=>x.status===filter);const list=useMemo(()=>[...filtered].sort((a,b)=>sort==="DUE_ASC"?+new Date(a.dueDate)-+new Date(b.dueDate):sort==="DUE_DESC"?+new Date(b.dueDate)-+new Date(a.dueDate):sort==="START_ASC"?+new Date(a.startDate)-+new Date(b.startDate):sort==="START_DESC"?+new Date(b.startDate)-+new Date(a.startDate):sort==="TITLE_ASC"?a.title.localeCompare(b.title,"uk"):b.title.localeCompare(a.title,"uk")),[filtered,sort]);return <><div className="hero-row"><div><h1>Робота</h1><p className="muted">Активні та завершені/прострочені записи до одного місяця. Старші переходять в історію.</p></div>{user.role!=="EMPLOYEE"&&<button className="primary" onClick={create}><Plus/>Створити</button>}</div>{user.role==="EMPLOYEE"&&dueSoon.length>0&&<div className="notice urgent-notice"><AlertTriangle/><div><b>Увага: {dueSoon.length} {dueSoon.length===1?"запис скоро завершиться":"записи скоро завершаться"}</b><span>Найближчий термін: {fmt([...dueSoon].sort((a,b)=>+new Date(a.dueDate)-+new Date(b.dueDate))[0].dueDate)}. Перевірте завдання та чеклісти з дедлайном у найближчі 24 години.</span></div></div>}<div className="stats"><Stat icon={<ClipboardCheck/>} value={counts.working} label="В роботі"/><Stat icon={<Clock3/>} value={counts.progress} label="Заплановано"/><Stat icon={<CheckCircle2/>} value={counts.done} label="Виконано за місяць"/><Stat icon={<AlertTriangle/>} value={counts.over} label="Прострочено за місяць"/></div>{user.role!=="EMPLOYEE"&&pending.length>0&&<PendingBox rows={pending} open={open} reload={load}/>}<div className="segmented wrap"><button className={filter==="ALL"?"active":""} onClick={()=>setFilter("ALL")}>Усі</button><button className={filter==="CHECKLIST"?"active":""} onClick={()=>setFilter("CHECKLIST")}>Чеклісти</button><button className={filter==="TASK"?"active":""} onClick={()=>setFilter("TASK")}>Завдання</button><button className={filter==="WORKING"?"active":""} onClick={()=>setFilter("WORKING")}>В роботі</button><button className={filter==="COMPLETED"?"active":""} onClick={()=>setFilter("COMPLETED")}>Виконані</button><button className={filter==="OVERDUE"?"active":""} onClick={()=>setFilter("OVERDUE")}>Прострочені</button></div><div className="sort-row"><label>Сортування<select value={sort} onChange={e=>setSort(e.target.value)}><option value="DUE_ASC">Термін: найближчі спочатку</option><option value="DUE_DESC">Термін: найпізніші спочатку</option><option value="START_ASC">Початок: найближчі спочатку</option><option value="START_DESC">Початок: найпізніші спочатку</option><option value="TITLE_ASC">Назва: А–Я</option><option value="TITLE_DESC">Назва: Я–А</option></select></label></div>{loading?<div className="empty">Завантаження…</div>:<div className="cards">{list.map(w=><WorkCard key={w.id} w={w} open={()=>open(w.id)}/>)}{!list.length&&<div className="empty">Записів немає.</div>}</div>}</>}
function Stat({icon,value,label}:{icon:React.ReactNode;value:number;label:string}){return <div className="stat"><div>{icon}</div><b>{value}</b><span>{label}</span></div>}

function HistoryPage({user,open}:{user:User;open:(id:string)=>void}){const[data,setData]=useState<Work[]>([]),[users,setUsers]=useState<User[]>([]),[loading,setLoading]=useState(true),[q,setQ]=useState(""),[type,setType]=useState("ALL"),[status,setStatus]=useState("ALL"),[assigneeId,setAssigneeId]=useState("ALL"),[from,setFrom]=useState(""),[to,setTo]=useState("");useEffect(()=>{Promise.all([api("/history").then(setData),user.role!=="EMPLOYEE"?api("/users").then(setUsers):Promise.resolve()]).finally(()=>setLoading(false))},[]);const filtered=useMemo(()=>data.filter(w=>{if(type!=="ALL"&&w.type!==type)return false;if(status!=="ALL"&&w.status!==status)return false;if(assigneeId!=="ALL"&&!assignees(w).some(u=>u.id===assigneeId))return false;if(q.trim()&&!`${w.title} ${w.description||""} ${assignees(w).map(x=>x.name).join(" ")}`.toLowerCase().includes(q.trim().toLowerCase()))return false;const d=new Date(w.completedAt||w.dueDate);if(from&&d<new Date(from+"T00:00:00"))return false;if(to&&d>new Date(to+"T23:59:59"))return false;return true}),[data,q,type,status,assigneeId,from,to]);const reset=()=>{setQ("");setType("ALL");setStatus("ALL");setAssigneeId("ALL");setFrom("");setTo("")};return <><div className="hero-row"><div><h1>Історія</h1><p className="muted">Виконані та прострочені записи старше одного місяця.</p></div></div><section className="panel history-filter"><div className="filter-title"><Filter/><b>Фільтр архіву</b><span>{filtered.length} з {data.length}</span></div><div className="history-filter-grid"><label className="search-field">Пошук<div><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Назва, опис або працівник"/></div></label><label>Тип<select value={type} onChange={e=>setType(e.target.value)}><option value="ALL">Усі типи</option><option value="CHECKLIST">Чеклісти</option><option value="TASK">Завдання</option></select></label><label>Статус<select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">Усі статуси</option><option value="COMPLETED">Виконані</option><option value="OVERDUE">Прострочені</option></select></label>{user.role!=="EMPLOYEE"&&<label>Виконавець<select value={assigneeId} onChange={e=>setAssigneeId(e.target.value)}><option value="ALL">Усі працівники</option>{users.map(u=><option value={u.id} key={u.id}>{u.name} — {u.position}</option>)}</select></label>}<label>Від<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>До<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><button className="secondary filter-reset" onClick={reset}>Скинути</button></div></section>{loading?<div className="empty">Завантаження…</div>:<div className="cards">{filtered.map(w=><WorkCard key={w.id} w={w} open={()=>open(w.id)}/>)}{!filtered.length&&<div className="empty">За вибраними фільтрами нічого не знайдено.</div>}</div>}</>}

function WorkCard({w,open}:{w:Work;open:()=>void}){const done=w.items?.filter(i=>i.status==="DONE").length||0,blocked=w.items?.filter(i=>i.status==="BLOCKED").length||0,pct=w.type==="TASK"?(w.status==="COMPLETED"?100:0):(w.items?.length?Math.round(done/w.items.length*100):0),people=assignees(w);return <button className={`check-card ${w.status==="OVERDUE"?"overdue-card":""}`} onClick={open}><div className="check-top"><div className="type-stack"><span className={`kind ${w.type.toLowerCase()}`}>{w.type==="TASK"?<FileCheck2/>:<ClipboardCheck/>}{w.type==="TASK"?"Завдання":"Чекліст"}</span><Status status={w.status}/></div>{w.recurrence!=="NONE"&&<span className="repeat"><RefreshCcw/> {w.recurrence==="MONTHLY"?"Щомісяця":"Щотижня"}</span>}</div><h3>{w.title}</h3><p>{w.description||"Без опису"}</p>{w.type==="CHECKLIST"&&<><div className="progress"><i style={{width:`${pct}%`}}/></div><div className="check-meta"><span><CheckCircle2/>{done}/{w.items?.length||0}</span>{blocked>0&&<span className="danger"><AlertTriangle/>{blocked}</span>}<span><CalendarClock/>Старт: {fmt(w.startDate)}</span><span><Clock3/>До: {fmt(w.dueDate)}</span></div></>}{w.type==="TASK"&&<div className="check-meta task-meta"><span><CalendarClock/>Старт: {fmt(w.startDate)}</span><span><Clock3/>До: {fmt(w.dueDate)}</span>{w.taskBlockedReason&&<span className="danger"><AlertTriangle/>Є причина невиконання</span>}</div>}<div className="creator-line"><UserCog/>Створив: <b>{w.createdBy?.name||"—"}</b></div><div className="assignee multi-assignee"><div className="avatar-stack">{people.slice(0,3).map((u,n)=><div className="avatar small" key={u.id} style={{zIndex:5-n}}>{u.name[0]}</div>)}{people.length>3&&<div className="avatar small more">+{people.length-3}</div>}</div><div><b>{people.map(x=>x.name).join(", ")}</b><span>{people.length===1?people[0].position:`${people.length} виконавців`}</span></div></div></button>}
function Status({status}:{status:Status}){const names:any={SCHEDULED:"Заплановано",OPEN:"Відкрито",IN_PROGRESS:"В роботі",BLOCKED:"Є проблема",COMPLETED:"Виконано",OVERDUE:"Прострочено"};return <span className={`status ${status.toLowerCase()}`}>{names[status]}</span>}

function PendingBox({rows,open,reload}:{rows:PendingRequest[];open:(id:string)=>void;reload:()=>void}){return <section className="pending-box"><div className="section-head"><div><h3>Запити на відтермінування</h3><span>{rows.length} очікує рішення</span></div></div><div className="pending-list">{rows.map(r=><div className="pending-row" key={r.id}><div><b>{r.checklist.title}</b><span>{r.requester.name}: {r.reason}</span><small>Поточний термін: {fmt(r.checklist.dueDate)}</small></div><div className="pending-actions"><button onClick={()=>open(r.checklist.id)}>Відкрити</button><DecisionButton request={r} reload={reload}/></div></div>)}</div></section>}
function DecisionButton({request,reload}:{request:PendingRequest;reload:()=>void}){const[show,setShow]=useState(false),[newDueDate,setNewDueDate]=useState(toLocalInput(request.checklist.dueDate)),[note,setNote]=useState("");const decide=async(decision:"APPROVED"|"REJECTED")=>{try{await api(`/postpone-requests/${request.id}/decision`,{method:"POST",body:JSON.stringify({decision,newDueDate:decision==="APPROVED"?new Date(newDueDate).toISOString():undefined,note})});setShow(false);reload()}catch(e:any){alert(e.message)}};return <>{<button className="primary" onClick={()=>setShow(true)}>Рішення</button>}{show&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>Рішення щодо відтермінування</h2><p>{request.checklist.title}</p></div><button className="icon" onClick={()=>setShow(false)}><X/></button></div><div className="info-note"><b>Причина працівника</b><p>{request.reason}</p></div><label>Новий термін<input type="datetime-local" value={newDueDate} onChange={e=>setNewDueDate(e.target.value)}/></label><label>Коментар керівника (необов'язково)<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Буде додано до системного коментаря про відтермінування"/></label><div className="modal-actions split"><button onClick={()=>decide("REJECTED")}>Не погодити</button><button className="primary" onClick={()=>decide("APPROVED")}>Погодити новий термін</button></div></div></div>}</>}

function WorkDetail({id,user,back,changed}:{id:string;user:User;back:()=>void;changed:()=>void}){const[w,setW]=useState<Work|null>(null),[comment,setComment]=useState(""),[blocked,setBlocked]=useState<Item|null>(null),[reason,setReason]=useState(""),[taskAction,setTaskAction]=useState<"DONE"|"BLOCKED"|null>(null),[taskText,setTaskText]=useState(""),[postpone,setPostpone]=useState(false),[postponeReason,setPostponeReason]=useState(""),[postponeDue,setPostponeDue]=useState(""),[edit,setEdit]=useState(false);const load=()=>api(`/checklists/${id}`).then(setW);useEffect(()=>{load()},[id]);if(!w)return <div className="empty">Завантаження…</div>;const canEdit=user.role!=="EMPLOYEE";const setItem=async(item:Item,status:Item["status"],blockedReason?:string)=>{try{await api(`/items/${item.id}`,{method:"PATCH",body:JSON.stringify({status,blockedReason})});setBlocked(null);setReason("");load();changed()}catch(e:any){alert(e.message)}};const photo=async(item:Item,file:File)=>{const fd=new FormData();fd.append("photo",file);try{await api(`/items/${item.id}/photo`,{method:"POST",body:fd});load()}catch(e:any){alert(e.message)}};const addComment=async()=>{if(!comment.trim())return;await api(`/checklists/${id}/comments`,{method:"POST",body:JSON.stringify({text:comment})});setComment("");load()};const taskSave=async()=>{try{await api(`/checklists/${id}/task-state`,{method:"POST",body:JSON.stringify({status:taskAction,comment:taskText})});setTaskAction(null);setTaskText("");load();changed()}catch(e:any){alert(e.message)}};const directPostpone=user.role!=="EMPLOYEE"&&w.createdBy?.id===user.id;const sendPostpone=async()=>{try{await api(`/checklists/${id}/postpone`,{method:"POST",body:JSON.stringify({reason:postponeReason,newDueDate:directPostpone&&postponeDue?new Date(postponeDue).toISOString():undefined})});setPostpone(false);setPostponeReason("");setPostponeDue("");load();changed()}catch(e:any){alert(e.message)}};const done=w.items?.filter(i=>i.status==="DONE").length||0,pending=w.postponeRequests?.find(r=>r.status==="PENDING"),people=assignees(w);return <><button className="back" onClick={back}>← Назад</button><div className="detail-head"><div><div className="detail-badges"><span className={`kind ${w.type.toLowerCase()}`}>{w.type==="TASK"?<FileCheck2/>:<ClipboardCheck/>}{w.type==="TASK"?"Завдання":"Чекліст"}</span><Status status={w.status}/></div><h1>{w.title}</h1><p className="muted">{w.description||"Без опису"}</p><div className="detail-created">Створив: <b>{w.createdBy?.name||"—"}</b></div><div className="detail-actions"><button className="secondary" disabled={!!pending||w.status==="COMPLETED"} onClick={()=>{setPostponeDue(toLocalInput(w.dueDate));setPostpone(true)}}><CalendarClock/> {pending?"Очікує погодження":"Відтермінувати"}</button>{canEdit&&<button className="secondary" onClick={()=>setEdit(true)}><Pencil/>Редагувати</button>}</div></div><div className="deadline"><span>Початок</span><b>{fmt(w.startDate)}</b><span>Термін виконання</span><b>{fmt(w.dueDate)}</b><small>{people.map(x=>`${x.name} · ${x.position}`).join(" • ")}</small></div></div>{pending&&<div className="notice"><CalendarClock/><div><b>Запит на відтермінування очікує рішення</b><span>{pending.reason}</span></div></div>}{w.type==="CHECKLIST"?<ChecklistBody w={w} done={done} setItem={setItem} setBlocked={i=>{setBlocked(i);setReason(i.blockedReason||"")}} photo={photo}/>:<TaskBody w={w} action={a=>{setTaskAction(a);setTaskText(a==="BLOCKED"?(w.taskBlockedReason||""):(w.taskComment||""))}}/>}<section className="panel comments standalone"><h2><MessageSquare/> Коментарі</h2><div className="comment-list">{w.comments?.map(x=><div className={`comment ${x.text.startsWith("Було відтерміновано до")?"system-comment":""}`} key={x.id}><div className="avatar small">{x.author.name[0]}</div><div><b>{x.author.name}</b><span>{new Date(x.createdAt).toLocaleString(getLang()==="uk"?"uk-UA":"en-GB",{hour12:false})}</span><p>{x.text}</p></div></div>)}{!w.comments?.length&&<p className="muted">Коментарів поки немає.</p>}</div><textarea placeholder="Написати коментар…" value={comment} onChange={e=>setComment(e.target.value)}/><button className="primary" onClick={addComment}>Додати коментар</button></section>{blocked&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>Причина невиконання</h2><p>Вкажіть, чому пункт неможливо виконати.</p></div><button className="icon" onClick={()=>setBlocked(null)}><X/></button></div><textarea autoFocus value={reason} onChange={e=>setReason(e.target.value)}/><div className="modal-actions"><button onClick={()=>setBlocked(null)}>Скасувати</button><button className="warning-btn" disabled={!reason.trim()} onClick={()=>setItem(blocked,"BLOCKED",reason)}>Зберегти причину</button></div></div></div>}{taskAction&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>{taskAction==="DONE"?"Завдання виконано":"Не можу виконати завдання"}</h2><p>{taskAction==="DONE"?"Коментар необов'язковий.":"Причина невиконання обов'язкова."}</p></div><button className="icon" onClick={()=>setTaskAction(null)}><X/></button></div><textarea autoFocus placeholder={taskAction==="DONE"?"Що було зроблено (необов'язково)…":"Вкажіть причину…"} value={taskText} onChange={e=>setTaskText(e.target.value)}/><div className="modal-actions"><button onClick={()=>setTaskAction(null)}>Скасувати</button><button className={taskAction==="DONE"?"primary":"warning-btn"} disabled={taskAction==="BLOCKED"&&!taskText.trim()} onClick={taskSave}>Підтвердити</button></div></div></div>}{postpone&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>{directPostpone?"Відтермінувати":"Запит на відтермінування"}</h2><p>{directPostpone?"Ви створили цей запис, тому погодження не потрібне.":"Дедлайн не зміниться, доки керівник не погодить запит."}</p></div><button className="icon" onClick={()=>setPostpone(false)}><X/></button></div>{directPostpone&&<label>Новий термін<input type="datetime-local" value={postponeDue} onChange={e=>setPostponeDue(e.target.value)}/></label>}<label>Причина / коментар<textarea autoFocus value={postponeReason} onChange={e=>setPostponeReason(e.target.value)} placeholder="Чому потрібне відтермінування?"/></label><div className="modal-actions"><button onClick={()=>setPostpone(false)}>Скасувати</button><button className="primary" disabled={postponeReason.trim().length<3||(directPostpone&&!postponeDue)} onClick={sendPostpone}>{directPostpone?"Відтермінувати":"Надіслати запит"}</button></div></div></div>}{edit&&<WorkEditor work={w} close={()=>setEdit(false)} done={()=>{setEdit(false);load();changed()}}/>}</>}
function ChecklistBody({w,done,setItem,setBlocked,photo}:{w:Work;done:number;setItem:(i:Item,s:Item["status"],r?:string)=>void;setBlocked:(i:Item)=>void;photo:(i:Item,f:File)=>void}){const pct=Math.round(done/(w.items?.length||1)*100)||0;return <section className="panel"><div className="section-head"><div><h2>Пункти чекліста</h2><span>{done} з {w.items?.length||0} виконано</span></div><b>{pct}%</b></div><div className="progress large"><i style={{width:`${pct}%`}}/></div><div className="item-list">{w.items?.map((i,n)=><div className={`item-row ${i.status.toLowerCase()}`} key={i.id}><div className="item-num">{n+1}</div><div className="item-body"><b>{i.title}</b>{i.description&&<p>{i.description}</p>}{i.status==="BLOCKED"&&<div className="reason"><AlertTriangle/>{i.blockedReason}</div>}{i.attachments?.length>0&&<div className="photos">{i.attachments.map(a=><a href={a.filePath} target="_blank" rel="noreferrer" key={a.id}><img src={a.filePath}/></a>)}</div>}<div className="item-actions"><button onClick={()=>setItem(i,"DONE")} className={i.status==="DONE"?"selected":""}><CheckCircle2/>Виконано</button><button onClick={()=>setBlocked(i)} className={i.status==="BLOCKED"?"selected warning":""}><AlertTriangle/>Не можу виконати</button><label className="upload"><Camera/>Фото<input type="file" accept="image/*" capture="environment" onChange={e=>e.target.files?.[0]&&photo(i,e.target.files[0])}/></label>{i.requiresPhoto&&<span className="required">Фото обов'язкове</span>}</div></div></div>)}</div></section>}
function TaskBody({w,action}:{w:Work;action:(a:"DONE"|"BLOCKED")=>void}){return <section className="panel task-panel"><div className="task-icon"><FileCheck2/></div><div><h2>Завдання</h2><p className="muted">{w.description||"Опис не вказаний"}</p>{w.taskComment&&<div className="result-box success"><b>Коментар після виконання</b><p>{w.taskComment}</p></div>}{w.taskBlockedReason&&<div className="result-box fail"><b>Причина невиконання</b><p>{w.taskBlockedReason}</p></div>}{w.status!=="COMPLETED"&&<div className="task-actions"><button className="primary" onClick={()=>action("DONE")}><CheckCircle2/>Виконав</button><button className="warning-btn" onClick={()=>action("BLOCKED")}><AlertTriangle/>Не можу виконати</button></div>}</div></section>}

function UsersPage({user}:{user:User}){const[users,setUsers]=useState<User[]>([]),[show,setShow]=useState(false),[edit,setEdit]=useState<User|null>(null);const load=()=>api("/users").then(setUsers);useEffect(()=>{load()},[]);const toggle=async(u:User)=>{try{await api(`/users/${u.id}`,{method:"PATCH",body:JSON.stringify({active:u.active===false})});load()}catch(e:any){alert(e.message)}};const remove=async(u:User)=>{if(!confirm(`${ui("Видалити користувача","Delete user")} ${u.name}? ${ui("Його історія виконання буде збережена.","Their execution history will be preserved.")}`))return;try{await api(`/users/${u.id}`,{method:"DELETE"});load()}catch(e:any){alert(e.message)}};return <><div className="hero-row"><div><h1>Користувачі</h1><p className="muted">Працівники, посади та рівні доступу.</p></div>{user.role==="ADMIN"&&<button className="primary" onClick={()=>setShow(true)}><Plus/>Додати користувача</button>}</div><div className="user-grid">{users.map(u=><div className={`user-card ${u.active===false?"user-disabled":""}`} key={u.id}><div className="avatar large">{u.name[0]}</div><div className="user-main"><h3>{u.name}</h3><p>@{u.username}</p><div className="user-tags"><span><Briefcase/>{u.position}</span><span><ShieldCheck/>{roleLabel(u.role)}</span><span>{u.active===false?"Заблокований":"Активний"}</span>{u.telegramChatId&&<span>Telegram ✓</span>}</div></div>{user.role==="ADMIN"&&<div className="user-actions"><button className="icon" title="Редагувати" onClick={()=>setEdit(u)}><UserCog/></button><button className="icon" title={u.active===false?"Розблокувати":"Заблокувати"} onClick={()=>toggle(u)}>{u.active===false?<Unlock/>:<Lock/>}</button><button className="icon danger-icon" title="Видалити" onClick={()=>remove(u)}><Trash2/></button></div>}<span className={u.active===false?"dot off":"dot"}/></div>)}</div>{show&&<CreateUser close={()=>setShow(false)} done={()=>{setShow(false);load()}}/>}{edit&&<EditUser target={edit} close={()=>setEdit(null)} done={()=>{setEdit(null);load()}}/>}</>}
function CreateUser({close,done}:{close:()=>void;done:()=>void}){const[f,setF]=useState({name:"",username:"",password:"",position:"",role:"EMPLOYEE",telegramChatId:""});const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await api("/users",{method:"POST",body:JSON.stringify(f)});done()}catch(e:any){alert(e.message)}};return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="modal-head"><div><h2>Новий користувач</h2><p>Створіть обліковий запис працівника.</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="form-grid"><label>Ім'я<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Ім'я користувача<input required minLength={3} value={f.username} onChange={e=>setF({...f,username:e.target.value})}/></label><label>Посада<input required value={f.position} onChange={e=>setF({...f,position:e.target.value})}/></label><label>Роль<select value={f.role} onChange={e=>setF({...f,role:e.target.value})}><option value="EMPLOYEE">Працівник</option><option value="MANAGER">Менеджер</option><option value="ADMIN">Адміністратор</option></select></label><label>Telegram Chat ID <small>(необов'язково)</small><input value={f.telegramChatId} onChange={e=>setF({...f,telegramChatId:e.target.value})} placeholder="Напр. 123456789"/></label><label className="full">Тимчасовий пароль<input required minLength={8} type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})}/></label></div><div className="modal-actions"><button type="button" onClick={close}>Скасувати</button><button className="primary">Створити</button></div></form></div>}
function EditUser({target,close,done}:{target:User;close:()=>void;done:()=>void}){const[f,setF]=useState({name:target.name,username:target.username,position:target.position,role:target.role,password:"",telegramChatId:target.telegramChatId||""});const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const payload:any={name:f.name,username:f.username,position:f.position,role:f.role,telegramChatId:f.telegramChatId};if(f.password)payload.password=f.password;await api(`/users/${target.id}`,{method:"PATCH",body:JSON.stringify(payload)});done()}catch(e:any){alert(e.message)}};return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="modal-head"><div><h2>Редагування користувача</h2><p>Змініть дані, роль або встановіть новий тимчасовий пароль.</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="form-grid"><label>Ім'я<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Ім'я користувача<input required minLength={3} value={f.username} onChange={e=>setF({...f,username:e.target.value})}/></label><label>Посада<input required value={f.position} onChange={e=>setF({...f,position:e.target.value})}/></label><label>Роль<select value={f.role} onChange={e=>setF({...f,role:e.target.value as Role})}><option value="EMPLOYEE">Працівник</option><option value="MANAGER">Менеджер</option><option value="ADMIN">Адміністратор</option></select></label><label>Telegram Chat ID <small>(необов'язково)</small><input value={f.telegramChatId} onChange={e=>setF({...f,telegramChatId:e.target.value})} placeholder="Напр. 123456789"/></label><label className="full">Новий тимчасовий пароль <small>(необов'язково)</small><input minLength={8} type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})} placeholder="Залиште порожнім, щоб не змінювати"/></label></div><div className="modal-actions"><button type="button" onClick={close}>Скасувати</button><button className="primary">Зберегти</button></div></form></div>}
function WorkEditor({work,close,done}:{work?:Work;close:()=>void;done:()=>void}){const[users,setUsers]=useState<User[]>([]),[picker,setPicker]=useState(false);const initialIds=work?assignees(work).map(u=>u.id):[];const[f,setF]=useState<EditorState>({type:work?.type||"CHECKLIST",title:work?.title||"",description:work?.description||"",startDate:work?toLocalInput(work.startDate):toLocalInput(),dueDate:work?toLocalInput(work.dueDate):"",assigneeIds:initialIds,recurrence:work?.recurrence||"NONE",items:work?.items?.map(i=>({id:i.id,title:i.title,description:i.description||"",requiresPhoto:i.requiresPhoto}))||[{title:"",description:"",requiresPhoto:false}]});useEffect(()=>{api("/users").then((u:User[])=>{const a=u.filter(x=>x.active!==false);setUsers(a);if(!f.assigneeIds.length&&a[0])setF(v=>({...v,assigneeIds:[a[0].id]}))})},[]);const item=(idx:number,k:keyof EditorItem,v:any)=>setF({...f,items:f.items.map((x,i)=>i===idx?{...x,[k]:v}:x)});const addAssignee=(id:string)=>{setF(v=>({...v,assigneeIds:v.assigneeIds.includes(id)?v.assigneeIds:[...v.assigneeIds,id]}));setPicker(false)};const removeAssignee=(id:string)=>setF(v=>({...v,assigneeIds:v.assigneeIds.filter(x=>x!==id)}));const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!f.assigneeIds.length){alert(ui("Додайте хоча б одного виконавця","Add at least one assignee"));return}try{if(new Date(f.dueDate)<=new Date(f.startDate)){alert(ui("Термін виконання має бути пізніше дати початку","The due date must be later than the start date"));return}const payload={...f,startDate:new Date(f.startDate).toISOString(),dueDate:new Date(f.dueDate).toISOString(),items:f.type==="CHECKLIST"?f.items:[]};await api(work?`/checklists/${work.id}`:"/checklists",{method:work?"PATCH":"POST",body:JSON.stringify(payload)});done()}catch(e:any){alert(e.message)}};const available=users.filter(u=>!f.assigneeIds.includes(u.id));return <div className="modal-backdrop"><form className="modal large-modal" onSubmit={submit}><div className="modal-head"><div><h2>{work?"Редагування":"Новий запис"}</h2><p>{work?"Змініть параметри, виконавців, дедлайн або пункти.":"Оберіть чекліст або окреме завдання."}</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="type-choice"><button type="button" className={f.type==="CHECKLIST"?"active":""} onClick={()=>setF({...f,type:"CHECKLIST"})}><ClipboardCheck/><b>Чекліст</b><span>Набір пунктів з окремими статусами</span></button><button type="button" className={f.type==="TASK"?"active":""} onClick={()=>setF({...f,type:"TASK"})}><FileCheck2/><b>Завдання</b><span>Один опис і загальний результат</span></button></div><div className="form-grid"><label className="full">Назва<input required value={f.title} onChange={e=>setF({...f,title:e.target.value})}/></label><label className="full">Опис<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><div className="full assignee-editor"><span className="field-label">Виконавці</span><div className="assignee-chips">{f.assigneeIds.map(id=>{const u=users.find(x=>x.id===id);return u?<span className="assignee-chip" key={id}><span className="avatar tiny">{u.name[0]}</span>{u.name}<button type="button" onClick={()=>removeAssignee(id)}><X/></button></span>:null})}<div className="add-person-wrap"><button type="button" className="add-person" onClick={()=>setPicker(!picker)}><Plus/></button>{picker&&<div className="person-picker">{available.map(u=><button type="button" key={u.id} onClick={()=>addAssignee(u.id)}><span className="avatar tiny">{u.name[0]}</span><span><b>{u.name}</b><small>{u.position}</small></span></button>)}{!available.length&&<div className="picker-empty">Усі користувачі вже додані</div>}</div>}</div></div></div><label>Дата і час початку<input required type="datetime-local" value={f.startDate} onChange={e=>setF({...f,startDate:e.target.value})}/></label><label>Термін виконання<input required type="datetime-local" value={f.dueDate} onChange={e=>setF({...f,dueDate:e.target.value})}/></label><label>Повторення<select value={f.recurrence} onChange={e=>setF({...f,recurrence:e.target.value as EditorState["recurrence"]})}><option value="NONE">Не повторювати</option><option value="WEEKLY">Щотижня</option><option value="MONTHLY">Щомісяця</option></select></label></div>{f.type==="CHECKLIST"&&<div className="items-editor"><div className="section-head"><div><h3>Пункти чекліста</h3><span>Фото можна зробити обов'язковим для окремих пунктів.</span></div><button type="button" onClick={()=>setF({...f,items:[...f.items,{title:"",description:"",requiresPhoto:false}]})}><Plus/>Додати пункт</button></div>{f.items.map((x,i)=><div className="edit-item" key={x.id||i}><span>{i+1}</span><div><input required placeholder="Назва пункту" value={x.title} onChange={e=>item(i,"title",e.target.value)}/><input placeholder="Короткий опис або інструкція" value={x.description} onChange={e=>item(i,"description",e.target.value)}/><label className="check"><input type="checkbox" checked={x.requiresPhoto} onChange={e=>item(i,"requiresPhoto",e.target.checked)}/> Вимагати фото</label></div>{f.items.length>1&&<button type="button" className="icon" onClick={()=>setF({...f,items:f.items.filter((_,n)=>n!==i)})}><X/></button>}</div>)}</div>}<div className="modal-actions"><button type="button" onClick={close}>Скасувати</button><button className="primary">{work?"Зберегти зміни":"Створити"}</button></div></form></div>}

createRoot(document.getElementById("root")!).render(<App/>);
